css:
.rsr-root[data-theme='onepage'] { padding: 0; font-size: 14px; }
.rsr-root[data-theme='onepage'] #resume { max-width: none; margin: 0; padding: 52px 60px; border: none; box-shadow: none; }

.rsr-root[data-theme='onepage'] {background: #EEEEEE;
  font: 12px "Times New Roman", Times, sans-serif;
  line-height: 1.4;
  margin: 40px 0; }
.rsr-root[data-theme='onepage'] em {color: #999; }
.rsr-root[data-theme='onepage'] p {line-height: 1.4; }
.rsr-root[data-theme='onepage'] ul {margin-bottom: 0; }
.rsr-root[data-theme='onepage'] li {margin-bottom: 2px; }
.rsr-root[data-theme='onepage'] a {text-decoration: none; }
.rsr-root[data-theme='onepage'] #resume {margin: 0 auto;
  max-width: 600px;
  padding: 80px 100px;
  background: #fff;
  border: 1px solid #ccc;
  box-shadow: 2px 2px 4px #aaa;
  -webkit-box-shadow: 2px 2px 4px #aaa; }
.rsr-root[data-theme='onepage'] .coursesList {width: 28%;
  vertical-align: top;
  display: inline-block; }
.rsr-root[data-theme='onepage'] .largeFont {font-size: 20px; }
.rsr-root[data-theme='onepage'] .smallFont {font-size: 12px; }
.rsr-root[data-theme='onepage'] .sectionBlock {display: flex;
  width: 100%; }
.rsr-root[data-theme='onepage'] .sectionName {width: 18%;
  vertical-align: top;
  display: inline-block; }
.rsr-root[data-theme='onepage'] .sectionContent {width: 80%;
  vertical-align: top;
  display: inline-block; }
.rsr-root[data-theme='onepage'] .sectionContent ul {padding-left: 20px;
  margin-top: 6px;
  list-style-type: circle; }
.rsr-root[data-theme='onepage'] .sectionContent .title {font-weight: bold; }
.rsr-root[data-theme='onepage'] .sectionContent .date {float: right; }
.rsr-root[data-theme='onepage'] .sectionContent .separator {height: 14px; }
.rsr-root[data-theme='onepage'] .sectionLine {border-style: dashed;
  border-width: 1px;
  border-color: #CFCFCF;
  margin-top: 10px;
  margin-bottom: 10px; }
.rsr-root[data-theme='onepage'] .divider {font-weight: bold;
  margin-left: 5px;
  margin-right: 5px; }
.rsr-root[data-theme='onepage'] .summary {margin-top: 6px; }
.rsr-root[data-theme='onepage'] .skillBlock {margin-bottom: 4px; }
.rsr-root[data-theme='onepage'] .jobBlock {page-break-inside: avoid; }
